SELECT "Motos_2"."Vehiculo" AS "Vehiculo",   SUM("Motos_2"."InversionUS") AS "sum_Calculation_0061002123102817_ok",   SUM(CAST("Motos_2"."NumAnuncios" AS BIGINT)) AS "sum_NumAnuncios_ok",   CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) AS "yr_FECHA_ok" FROM "Motos_2" WHERE ((CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) = 2015) AND ("Motos_2"."Categoria" = 'MOTOCICLETAS') AND ("Motos_2"."Medio" = 'TELEVISION NACIONAL')) GROUP BY "Motos_2"."Vehiculo",   "yr_FECHA_ok";
